private void deliver(Bundle args,Result result){
  if (paused) {
    Log.i(Helper.TAG,"Deferring delivery task " + this);
    this.args=args;
    this.stored=result;
  }
 else {
    Log.i(Helper.TAG,"Delivery task " + this);
    try {
      if (result.ex == null)       onLoaded(args,(T)result.data);
 else       onException(args,result.ex);
    }
 catch (    RuntimeException ex) {
      Log.e(Helper.TAG,ex + "\n" + Log.getStackTraceString(ex));
    }
 finally {
      onDestroyed();
    }
  }
}
